CREATE TABLE public.payment_checkout_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, plan_id uuid NOT NULL REFERENCES public.subscription_plans(id), pagarme_customer_id text NOT NULL, pagarme_link_id text UNIQUE NOT NULL, payment_method text NOT NULL, amount_cents integer NOT NULL, is_single_payment boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.payment_checkout_sessions TO authenticated; GRANT ALL ON public.payment_checkout_sessions TO service_role; ALTER TABLE public.payment_checkout_sessions ENABLE ROW LEVEL SECURITY; CREATE POLICY checkout_read_own ON public.payment_checkout_sessions FOR SELECT TO authenticated USING(user_id = auth.uid()); CREATE TRIGGER update_checkout_timestamp BEFORE UPDATE ON public.payment_checkout_sessions FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column(); CREATE INDEX checkout_customer_idx ON public.payment_checkout_sessions(pagarme_customer_id, created_at DESC);
CREATE TABLE public.payment_webhook_receipts (event_key text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.payment_webhook_receipts TO service_role; ALTER TABLE public.payment_webhook_receipts ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.confirm_pagarme_payment(p_event_key text,p_user_id uuid,p_plan_id uuid,p_provider_subscription_id text,p_start timestamptz,p_end timestamptz,p_amount integer,p_method text,p_transaction_id text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; v_type public.subscription_type; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text || p_plan_id::text,0)); INSERT INTO public.payment_webhook_receipts(event_key) VALUES(p_event_key) ON CONFLICT DO NOTHING; IF NOT FOUND THEN RETURN NULL; END IF; SELECT subscription_type INTO STRICT v_type FROM public.subscription_plans WHERE id=p_plan_id; SELECT id INTO v_id FROM public.subscriptions WHERE user_id=p_user_id AND plan_id=p_plan_id AND (pagarme_subscription_id=p_provider_subscription_id OR p_provider_subscription_id IS NULL) ORDER BY created_at DESC LIMIT 1; IF v_id IS NULL THEN INSERT INTO public.subscriptions(user_id,plan_id,subscription_type,status,pagarme_subscription_id,current_period_start,current_period_end) VALUES(p_user_id,p_plan_id,v_type,'active',p_provider_subscription_id,p_start,p_end) RETURNING id INTO v_id; ELSE UPDATE public.subscriptions SET status='active',subscription_type=v_type,current_period_start=CASE WHEN current_period_end IS NULL OR p_end>=current_period_end THEN p_start ELSE current_period_start END,current_period_end=GREATEST(current_period_end,p_end),updated_at=now() WHERE id=v_id; END IF; INSERT INTO public.payments(subscription_id,user_id,pagarme_transaction_id,amount_cents,status,payment_method,paid_at) VALUES(v_id,p_user_id,p_transaction_id,p_amount,'paid',p_method,p_start); RETURN v_id; END $$; REVOKE ALL ON FUNCTION public.confirm_pagarme_payment(text,uuid,uuid,text,timestamptz,timestamptz,integer,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.confirm_pagarme_payment(text,uuid,uuid,text,timestamptz,timestamptz,integer,text,text) TO service_role;